#!/usr/bin/env bash
# Lance toutes les vérifications hors ligne (aucun réseau, aucun compte nécessaire) : bash outils/tests/tout.sh
set -u; cd "$(dirname "$0")/../.."; echec=0
etape() { echo "── $1"; shift; if "$@"; then :; else echec=1; fi; }
etape "Fichiers, liens, voix, règles de synthèse vocale" bash -c 'set -o pipefail; node outils/tests/verifier.mjs | tail -1'
etape "Droits (Créateur, invités, abonnés, gratuit)" bash -c 'set -o pipefail; node --test outils/tests/droits.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/droits.test.mjs >/dev/null 2>&1'
etape "Jetons Firebase (vérification serveur)" bash -c 'set -o pipefail; node --test outils/tests/jeton.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/jeton.test.mjs >/dev/null 2>&1'
etape "API (comptes, droits, invitations, admin, Stripe test, Premium, RGPD)" bash -c 'set -o pipefail; node --test --test-concurrency=1 outils/tests/api.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test --test-concurrency=1 outils/tests/api.test.mjs >/dev/null 2>&1'
etape "Premium (Créateur, Premium, Famille, Gratuit, anonyme, révocation, expiration, voir comme)" bash -c 'set -o pipefail; node --test --test-concurrency=1 outils/tests/premium.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test --test-concurrency=1 outils/tests/premium.test.mjs >/dev/null 2>&1'
etape "Grand Voyage : zones Premium fermées/ouvertes (données, sans rendu 3D)" bash -c 'set -o pipefail; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/voyage-regions.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --import ./outils/tests/three-factice/enregistrer.mjs --test outils/tests/voyage-regions.test.mjs >/dev/null 2>&1'
etape "Script local du rôle Créateur" bash -c 'set -o pipefail; node --test outils/tests/role-createur.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/role-createur.test.mjs >/dev/null 2>&1'
etape "Firestore REST (requêtes, conversions, compte de service)" bash -c 'set -o pipefail; node --test outils/tests/firestore.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/firestore.test.mjs >/dev/null 2>&1'
etape "Restauration de la base des comptes (export → age → import → API)" bash -c 'set -o pipefail; node --test outils/tests/restauration.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/restauration.test.mjs >/dev/null 2>&1'
etape "Garde-fou de branche (main refusée)" bash -c 'set -o pipefail; node --test outils/tests/garde-branche.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/garde-branche.test.mjs >/dev/null 2>&1'
etape "Envoi du pack vers R2 (simulation, garde-fous)" bash -c 'set -o pipefail; node --test outils/tests/envoi-r2.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/envoi-r2.test.mjs >/dev/null 2>&1'
etape "Configuration : outil de contrôle" bash -c 'set -o pipefail; node --test outils/tests/verifier-configuration.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/verifier-configuration.test.mjs >/dev/null 2>&1'
etape "Parcours de compte complet (serveur local, simulation)" bash -c 'set -o pipefail; S=$(bash outils/tests/parcours-reel.sh); echo "$S" | tail -1; echo "$S" | grep -q " 0 échoués"'
etape "Dossier publié (aucune fuite)" bash -c 'set -o pipefail; node outils/construire.mjs >/dev/null && node outils/tests/verifier-dist.mjs | tail -1'
etape "Aucune fuite Premium (dépôt public + dist)" bash -c 'set -o pipefail; node outils/tests/fuite-premium.mjs | tail -1; node outils/tests/fuite-premium.mjs >/dev/null'
etape "Exercice de restauration chiffrée" bash -c 'set -o pipefail; bash outils/sauvegarde/exercice-restauration.sh | tail -1'
etape "Secrets : configuration invalide sans fuite" bash -c 'set -o pipefail; node --test outils/tests/secrets.test.mjs 2>&1 | grep -E "^# (pass|fail)" | tr "\n" " "; echo; node --test outils/tests/secrets.test.mjs >/dev/null 2>&1'
if [ "${EMULATEURS_FIREBASE:-0}" = 1 ]; then etape "Émulateurs officiels Firebase : règles, base REST, restauration, rôle Créateur" bash -c 'set -o pipefail; bash outils/tests/emulateurs-firebase.sh | grep -E "^(── |not ok|# (tests|pass|fail))"'; fi
if [ "${NAVIGATEUR:-0}" = 1 ]; then etape "Parcours complets dans Chrome (émulateur local)" bash -c 'set -o pipefail; bash outils/tests/parcours.sh | tail -1'; etape "Bloc 3 dans Chrome : Premium, Chasse aux mots, aperçu Créateur, ordinateur + téléphone" bash -c 'bash outils/tests/parcours-bloc3.sh | tail -1'; fi
[ $echec -eq 0 ] && echo "TOUT EST VERT" || echo "AU MOINS UNE VÉRIFICATION A ÉCHOUÉ"; exit $echec
